function validate([colors]) {
  if (colors.length < 3 || colors.length > 100) return 'colors needs 3 to 100 tiles.';
  if (colors.some(v => v !== 0 && v !== 1)) return 'Each color is 0 (red) or 1 (blue).';
  return null;
}

