function numberOfAlternatingGroups(colors) {
  const n = colors.length;
  const differs = colors.map((color, i) => (color !== colors[(i + 1) % n] ? 1 : 0));
  let changes = differs[0] + differs[1];
  let groups = changes === 2 ? 1 : 0;
  for (let start = 1; start < n; start++) {
    changes -= differs[start - 1];
    changes += differs[(start + 1) % n];
    if (changes === 2) {
      groups++;
    }
  }
  return groups;
}

