function numberOfAlternatingGroups(colors) {
  // Write the circle as text, repeat its first two tiles at the end, and test every 3-character slice.
  const ring = colors.concat(colors.slice(0, 2)).join('');
  let count = 0;
  for (let i = 0; i < colors.length; i++) {
    const three = ring.slice(i, i + 3);
    if (three === '010' || three === '101') count++;
  }
  return count;
}

