function generate(rand, size) {
  const n = size === 'large' ? 90 + Math.floor(rand() * 11) : 3 + Math.floor(rand() * 6);
  // Mostly alternate, with a chance of repeating the previous color, so groups appear in varied numbers.
  const repeat = rand() * 0.6;
  const colors = [rand() < 0.5 ? 0 : 1];
  while (colors.length < n) {
    const last = colors[colors.length - 1];
    colors.push(rand() < repeat ? last : 1 - last);
  }
  return [colors];
}
